{"command":"python3 -c "
import requests
import re

# Try to get the abstract and content from the search results
url = 'https://www.mdpi.com/2076-2607/11/1/123'
try:
    response = requests.get(url)
    print('Status code:', response.status_code)

    if response.status_code == 200:
        text = response.text

        # Extract abstract
        abstract_pattern = r'<h2.*?Abstract.*?</h2>(.*?)<h2'
        abstract_match = re.search(abstract_pattern, text, re.DOTALL | re.IGNORECASE)
        if abstract_match:
            abstract = abstract_match.group(1).strip()
            print('ABSTRACT:')
            print(abstract[:2000])

        # Look for mentions of animals
        animal_keywords = ['goat', 'sheep', 'cow', 'animal', 'mammal', 'livestock', 'dairy', 'caprine']
        found_animals = {}
        for keyword in animal_keywords:
            matches = re.findall(keyword, text, re.IGNORECASE)
            if matches:
                found_animals[keyword] = len(matches)

        print('\nANIMAL MENTIONS:')
        for animal, count in found_animals.items():
            print(f'{animal}: {count} mentions')

    else:
        print('Failed to access paper directly')

except Exception as e:
    print(f'Error: {e}')
""}

